const items = $input.all();

// Datos originales que llegaron desde el workflow principal
const entrada =
  $('When Executed by Another Workflow')
    .first()
    .json;

const telegramId = String(
  entrada.TELEGRAM_ID ||
  entrada.chat_id ||
  ""
).trim();

const mensajeTelegram = String(
  entrada.MENSAJE_TELEGRAM ||
  ""
).trim();


// ======================================================
// VALIDAR TELEGRAM ID
// ======================================================

if (!telegramId) {
  throw new Error(
    JSON.stringify({
      etiqueta: "CAJA_TELEGRAM_ID_VACIO"
    })
  );
}


// ======================================================
// BUSCAR OPERACIONES ABIERTAS DEL USUARIO
// ======================================================

const pendientes = items
  .map(item => item.json)

  .filter(row => {

    const idFila = String(
      row.TELEGRAM_ID || ""
    ).trim();

    const estado = String(
      row.ESTADO || ""
    )
      .trim()
      .toUpperCase();

    return (
      idFila === telegramId &&
      estado !== "" &&
      estado !== "COMPLETADO" &&
      estado !== "CANCELADO"
    );
  });


// ======================================================
// SI YA EXISTE UNA OPERACIÓN ABIERTA
// ======================================================

if (pendientes.length > 0) {

  pendientes.sort((a, b) => {

    const fechaA =
      new Date(
        a.FECHA_CREACION || ""
      ).getTime();

    const fechaB =
      new Date(
        b.FECHA_CREACION || ""
      ).getTime();

    if (
      Number.isFinite(fechaA) &&
      Number.isFinite(fechaB) &&
      fechaA !== fechaB
    ) {
      return fechaB - fechaA;
    }

    return (
      Number(b.row_number || 0) -
      Number(a.row_number || 0)
    );
  });


  const pendiente =
    pendientes[0];


  return [
    {
      json: {

        ...pendiente,

        TELEGRAM_ID:
          telegramId,

        chat_id:
          telegramId,

        MENSAJE_TELEGRAM:
          mensajeTelegram,

        ID_OPERACION:
          pendiente.ID_OPERACION ||
          pendiente["ID OPERACION"] ||
          "",

        MESSAGE_ID:
          pendiente.MESSAGE_ID || "",

        ESTADO_ACTUAL:
          pendiente.ESTADO || "",

        ACCION_INICIO_CAJA:
          "REUTILIZAR_EXISTENTE"
      }
    }
  ];
}


// ======================================================
// NO EXISTE OPERACIÓN ABIERTA
// CREAR NUEVA
// ======================================================

const fecha =
  new Date();

const idOperacion =
  "OP_" +
  fecha.getFullYear() +
  String(
    fecha.getMonth() + 1
  ).padStart(2, "0") +
  String(
    fecha.getDate()
  ).padStart(2, "0") +
  "_" +
  String(
    fecha.getHours()
  ).padStart(2, "0") +
  String(
    fecha.getMinutes()
  ).padStart(2, "0") +
  String(
    fecha.getSeconds()
  ).padStart(2, "0") +
  "_" +
  telegramId;


let registradoPor =
  "DESCONOCIDO";

if (
  telegramId ===
  "941030473"
) {
  registradoPor =
    "EDWARD";
}

if (
  telegramId ===
  "1057242322"
) {
  registradoPor =
    "GABRIEL";
}


// ======================================================
// SALIDA NUEVA OPERACIÓN
// ======================================================

return [
  {
    json: {

      ...entrada,

      ID_OPERACION:
        idOperacion,

      TELEGRAM_ID:
        telegramId,

      chat_id:
        telegramId,

      MESSAGE_ID:
        "",

      ESTADO:
        "ESPERA_TIPO_MOVIMIENTO",

      TIPO_MOVIMIENTO:
        "",

      OPERACION:
        "",

      SERVICIO:
        "",

      MODALIDAD:
        "",

      DURACION:
        "",

      CLIENTE:
        "",

      CORREO:
        "",

      MONEDA:
        "",

      MONTO_SUGERIDO:
        "",

      MONTO_RECIBIDO:
        "",

      TASA:
        "",

      EQUIVALENTE_USD:
        "",

      METODO_PAGO:
        "",

      REGISTRADO_POR:
        registradoPor,

      ORIGEN:
        "MANUAL",

      FECHA_CREACION:
        fecha.toISOString(),

      MENSAJE_TELEGRAM:
        mensajeTelegram,

      ACCION_INICIO_CAJA:
        "CREAR_NUEVA"
    }
  }
];

const items = $input.all();


// ======================================================
// DATOS DE LA NUEVA EJECUCIÓN
// ======================================================

const entrada =
  $('When Executed by Another Workflow')
    .first()
    .json;


const telegramId = String(
  entrada.TELEGRAM_ID ||
  entrada.chat_id ||
  ""
).trim();


const accion = String(
  entrada.MENSAJE_TELEGRAM ||
  ""
).trim();


// ======================================================
// VALIDAR TELEGRAM ID
// ======================================================

if (!telegramId) {
  throw new Error(
    JSON.stringify({
      etiqueta: "CAJA_TELEGRAM_ID_VACIO",
      accion
    })
  );
}


// ======================================================
// BUSCAR SOLO OPERACIONES ABIERTAS
// ======================================================

const pendientes = items
  .map(item => item.json)

  .filter(row => {

    const estado = String(
      row.ESTADO || ""
    )
      .trim()
      .toUpperCase();


    const telegramIdFila = String(
      row.TELEGRAM_ID || ""
    ).trim();


    return (
      telegramIdFila === telegramId &&
      estado !== "COMPLETADO" &&
      estado !== "CANCELADO" &&
      estado !== ""
    );
  });


// ======================================================
// SI NO HAY OPERACIÓN ABIERTA
// ======================================================

if (pendientes.length === 0) {

  throw new Error(
    JSON.stringify({
      etiqueta:
        "CAJA_SIN_OPERACION_PENDIENTE",

      TELEGRAM_ID:
        telegramId,

      accion
    })
  );
}


// ======================================================
// ORDENAR DE MÁS RECIENTE A MÁS ANTIGUA
//
// PRIORIDAD:
//
// 1. FECHA_CREACION
// 2. row_number como respaldo
//
// ======================================================

pendientes.sort((a, b) => {

  const fechaA =
    new Date(
      a.FECHA_CREACION || ""
    ).getTime();

  const fechaB =
    new Date(
      b.FECHA_CREACION || ""
    ).getTime();


  const fechaAValida =
    Number.isFinite(fechaA);

  const fechaBValida =
    Number.isFinite(fechaB);


  // ----------------------------------------------------
  // SI LAS DOS FECHAS SON VÁLIDAS
  // ----------------------------------------------------

  if (
    fechaAValida &&
    fechaBValida &&
    fechaA !== fechaB
  ) {

    return fechaB - fechaA;
  }


  // ----------------------------------------------------
  // RESPALDO:
  // ROW NUMBER MÁS ALTO = MÁS RECIENTE
  // ----------------------------------------------------

  const rowA =
    Number(a.row_number || 0);

  const rowB =
    Number(b.row_number || 0);


  return rowB - rowA;
});


// ======================================================
// TOMAR SOLO LA OPERACIÓN MÁS RECIENTE
// ======================================================

const pendiente =
  pendientes[0];


// ======================================================
// VALIDAR OPERACIÓN SELECCIONADA
// ======================================================

const idOperacion = String(
  pendiente.ID_OPERACION ||
  pendiente["ID OPERACION"] ||
  ""
).trim();


if (!idOperacion) {

  throw new Error(
    JSON.stringify({
      etiqueta:
        "CAJA_OPERACION_SIN_ID",

      TELEGRAM_ID:
        telegramId,

      row_number:
        pendiente.row_number || ""
    })
  );
}


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      ...pendiente,

      TELEGRAM_ID:
        telegramId,

      chat_id:
        telegramId,

      // Lo que acaba de llegar desde Telegram
      ACCION_CAJA:
        accion,

      MENSAJE_TELEGRAM:
        accion,

      ID_OPERACION:
        idOperacion,

      MESSAGE_ID:
        pendiente.MESSAGE_ID || "",

      ESTADO_ACTUAL:
        String(
          pendiente.ESTADO || ""
        ).trim()
    }
  }
];

// Filtramos los items que tengan datos en la columna PRODUCTO_PRECIO
return items.filter(item => {
    // Verificamos si la propiedad existe y no está vacía
    const producto = item.json.PRODUCTO_PRECIO;
    return producto !== undefined && producto !== null && String(producto).trim() !== "";
}).map(item => {
    return {
        json: {
            producto: item.json.PRODUCTO_PRECIO,
            precio: item.json.VALOR_USD || "N/A" // Si no hay precio, pone N/A
        }
    };
});

