// ======================================================
// DATOS DE LA OPERACIÓN ACTUAL
// ======================================================

const operacionCaja = $('CODE - Resolver Caja').first().json;

const servicio = String(
  operacionCaja.SERVICIO || ""
).trim().toUpperCase();

const modalidad = String(
  operacionCaja.MODALIDAD || ""
).trim().toUpperCase();

const operacion = String(
  operacionCaja.OPERACION || ""
).trim().toUpperCase();

const duracion = Number(
  operacionCaja.DURACION || 1
);

const metodoPago = String(
  operacionCaja.METODO_PAGO || ""
).trim().toUpperCase();

const moneda = String(
  operacionCaja.MONEDA || ""
).trim().toUpperCase();


// ======================================================
// VERSIONES SOLO PARA MOSTRAR EN TELEGRAM
// NO MODIFICAN LOS VALORES INTERNOS
// ======================================================

const servicioMostrar =
  servicio.replace(/_/g, " ");

const modalidadMostrar =
  modalidad.replace(/_/g, " ");

const operacionMostrar =
  operacion.replace(/_/g, " ");


// ======================================================
// VALIDACIONES BÁSICAS
// ======================================================

if (!servicio) {
  throw new Error("SERVICIO vacío");
}

if (!modalidad) {
  throw new Error("MODALIDAD vacía");
}

if (!operacion) {
  throw new Error("OPERACION vacía");
}

if (
  !Number.isFinite(duracion) ||
  duracion < 1
) {
  throw new Error(
    `Duración inválida: ${operacionCaja.DURACION}`
  );
}

if (!metodoPago) {
  throw new Error("METODO_PAGO vacío");
}


// ======================================================
// LEER LOS ITEMS DEL MERGE
// Aquí esperamos principalmente los productos/precios
// ======================================================

const items = $input.all().map(item => item.json);


// ======================================================
// EXTRAER PRODUCTOS
// ======================================================

const productos = items.filter(item =>
  item.producto !== undefined &&
  item.precio !== undefined
);

if (!productos.length) {
  throw new Error(
    "No llegaron productos/precios desde el Merge"
  );
}


// ======================================================
// LEER TASA VIGENTE DIRECTAMENTE DEL NODO
// seleccionar tasa vigente
// ======================================================

const filaTasa =
  $('seleccionar tasa vigente').first().json;

const tasaPromedio = Number(
  filaTasa["Promedio Tasa"]
);

const tasaEsDeHoy =
  filaTasa.TASA_ES_DE_HOY === true;

const fechaTasaUsada =
  String(
    filaTasa.TASA_USADA_FECHA ||
    filaTasa.Dia ||
    ""
  ).trim();

const fechaHoyVzla =
  String(
    filaTasa.FECHA_HOY_VENEZUELA ||
    ""
  ).trim();


// ======================================================
// VALIDAR TASA
// ======================================================

if (
  !Number.isFinite(tasaPromedio) ||
  tasaPromedio <= 0
) {
  throw new Error(
    JSON.stringify({
      error: "TASA_INVALIDA",
      promedioTasa: filaTasa["Promedio Tasa"],
      fechaTasaUsada,
      fechaHoyVzla
    })
  );
}


// ======================================================
// NORMALIZAR NOMBRE DE PRODUCTO
// ======================================================

function normalizarTexto(valor) {

  return String(valor || "")
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\*/g, "")
    .replace(/[^\w\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}


// ======================================================
// BUSCAR PRODUCTO CORRECTO
// ======================================================

const productoEncontrado = productos.find(item => {

  const nombre = normalizarTexto(
    item.producto
  );

  const coincideServicio =
    servicio === "NETFLIX"
      ? nombre.includes("NETFLIX")
      : nombre.includes("FLUJOTV");

  const coincideModalidad =
    modalidad === "PERFIL"
      ? nombre.includes("PERFIL")
      : nombre.includes("COMPLETA");

  return (
    coincideServicio &&
    coincideModalidad
  );
});


// ======================================================
// VALIDAR PRODUCTO
// ======================================================

if (!productoEncontrado) {

  throw new Error(
    JSON.stringify({
      error: "PRECIO_NO_ENCONTRADO",
      servicio,
      modalidad,
      productosDisponibles:
        productos.map(p => p.producto)
    })
  );
}


// ======================================================
// PRECIO BASE
// ======================================================

const precioMensualUSD = Number(
  productoEncontrado.precio
);

if (
  !Number.isFinite(precioMensualUSD) ||
  precioMensualUSD <= 0
) {
  throw new Error(
    `Precio inválido: ${productoEncontrado.precio}`
  );
}


// ======================================================
// CALCULAR PRECIO SEGÚN DURACIÓN
// ======================================================

const equivalenteUSD =
  Number(
    (
      precioMensualUSD *
      duracion
    ).toFixed(2)
  );


// ======================================================
// CALCULAR MONTO SEGÚN MÉTODO
// ======================================================

let montoSugerido = 0;
let simboloMoneda = "";
let metodoMostrar = "";


// --------------------------
// PAGO MÓVIL → BS
// --------------------------

if (metodoPago === "PAGO_MOVIL") {

  montoSugerido =
    Number(
      (
        equivalenteUSD *
        tasaPromedio
      ).toFixed(2)
    );

  simboloMoneda = "Bs";

  metodoMostrar =
    "Pago Móvil";
}


// --------------------------
// ZELLE → USD
// --------------------------

else if (metodoPago === "ZELLE") {

  montoSugerido =
    equivalenteUSD;

  simboloMoneda = "USD";

  metodoMostrar =
    "Zelle";
}


// --------------------------
// BINANCE → USDT
// --------------------------

else if (metodoPago === "BINANCE") {

  montoSugerido =
    equivalenteUSD;

  simboloMoneda = "USDT";

  metodoMostrar =
    "Binance";
}


// --------------------------
// MÉTODO DESCONOCIDO
// --------------------------

else {

  throw new Error(
    `Método de pago no reconocido: ${metodoPago}`
  );
}


// ======================================================
// FORMATEAR MONTO PARA TELEGRAM
// ======================================================

function formatoMonto(numero) {

  return Number(numero)
    .toLocaleString(
      "es-VE",
      {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2
      }
    );
}

const montoMostrar =
  formatoMonto(montoSugerido);


// ======================================================
// FORMATEAR FECHA DE TASA
// ======================================================

function formatoFechaVzla(fechaISO) {

  const partes =
    String(fechaISO || "")
      .split("-");

  if (partes.length !== 3) {
    return fechaISO;
  }

  return `${partes[2]}/${partes[1]}/${partes[0]}`;
}

const fechaTasaMostrar =
  formatoFechaVzla(fechaTasaUsada);


// ======================================================
// ADVERTENCIA DE TASA
// SOLO PARA BS
// ======================================================

let advertenciaTasa = "";

if (
  metodoPago === "PAGO_MOVIL" &&
  !tasaEsDeHoy &&
  fechaTasaUsada
) {

  advertenciaTasa =
`\n\nℹ️ _Usando la última tasa disponible del ${fechaTasaMostrar}._`;
}


// ======================================================
// MENSAJE
// ======================================================

const textoMensaje =
`💰 *REGISTRO DE INGRESO*

${servicioMostrar} · ${operacionMostrar} · ${modalidadMostrar}
Duración: *${duracion} ${duracion === 1 ? "mes" : "meses"}*
Pago: *${metodoMostrar}*

Monto sugerido: *${montoMostrar} ${simboloMoneda}*${advertenciaTasa}

¿Deseas registrar este monto?`;


// ======================================================
// BOTONES
// ======================================================

const botones = [

  [
    {
      text: `✅ USAR ${montoMostrar} ${simboloMoneda}`,
      callback_data: "CAJA_MONTO_CONFIRMAR"
    }
  ],

  [
    {
      text: "✍️ CAMBIAR MONTO",
      callback_data: "CAJA_MONTO_MANUAL"
    }
  ],

  [
    {
      text: "⬅️ ATRÁS",
      callback_data: "CAJA_ATRAS"
    },

    {
      text: "❌ CANCELAR",
      callback_data: "CAJA_CANCELAR"
    }
  ]
];


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      ...operacionCaja,

      ESTADO:
        "ESPERA_CONFIRMACION_MONTO",

      PRECIO_MENSUAL_USD:
        precioMensualUSD,

      MONTO_SUGERIDO:
        montoSugerido,

      TASA:
        tasaPromedio,

      EQUIVALENTE_USD:
        equivalenteUSD,

      PRODUCTO_PRECIO:
        productoEncontrado.producto,

      TASA_ES_DE_HOY:
        tasaEsDeHoy,

      TASA_USADA_FECHA:
        fechaTasaUsada,

      FECHA_HOY_VENEZUELA:
        fechaHoyVzla,

      TEXTO_MENSAJE:
        textoMensaje,

      REPLY_MARKUP: {
        inline_keyboard: botones
      },

      ACCION_SISTEMA:
        "MOSTRAR_MONTO"
    }
  }
];

const filas = $input.all().map(i => i.json);

if (!filas.length) {
  throw new Error("No hay tasas disponibles");
}

// Fecha actual en Venezuela UTC-4
const ahora = new Date();

const vzla = new Date(
  ahora.getTime() - (4 * 60 * 60 * 1000)
);

const hoyVzla =
  vzla.getUTCFullYear() +
  "-" +
  String(vzla.getUTCMonth() + 1).padStart(2, "0") +
  "-" +
  String(vzla.getUTCDate()).padStart(2, "0");

// Filas con fecha válida
const validas = filas
  .filter(f => {
    const dia = String(f.Dia || "").trim();

    return /^\d{4}-\d{2}-\d{2}$/.test(dia);
  })
  .sort((a, b) => {
    return String(b.Dia)
      .localeCompare(String(a.Dia));
  });

if (!validas.length) {
  throw new Error(
    "No se encontró ninguna tasa con fecha válida"
  );
}

// Buscar tasa de hoy
const tasaHoy = validas.find(
  f => String(f.Dia).trim() === hoyVzla
);

// Si no hay de hoy, usar la última disponible
const seleccionada =
  tasaHoy || validas[0];

return [
  {
    json: {
      ...seleccionada,

      TASA_USADA_FECHA:
        String(seleccionada.Dia),

      TASA_ES_DE_HOY:
        String(seleccionada.Dia) === hoyVzla,

      FECHA_HOY_VENEZUELA:
        hoyVzla
    }
  }
];

const data = { ...$json };


// ======================================================
// HELPERS
// ======================================================

function btn(text, callback_data) {
  return {
    text,
    callback_data
  };
}

function teclado(...filas) {
  return filas;
}

function limpiar(valor) {
  return String(
    valor ?? ""
  ).trim();
}

function formatoMonto(numero) {
  return Number(numero || 0)
    .toLocaleString(
      "es-VE",
      {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }
    );
}

function simboloMoneda(moneda) {

  const valor = limpiar(moneda)
    .toUpperCase();

  if (valor === "BS") {
    return "Bs";
  }

  if (valor === "USD") {
    return "USD";
  }

  if (valor === "USDT") {
    return "USDT";
  }

  return valor;
}

function nombreMetodoPago(metodo) {

  const valor = limpiar(metodo)
    .toUpperCase();

  if (valor === "PAGO_MOVIL") {
    return "Pago Móvil";
  }

  if (valor === "ZELLE") {
    return "Zelle";
  }

  if (valor === "BINANCE") {
    return "Binance";
  }

  return metodo;
}


// ======================================================
// DATOS
// ======================================================

const pantalla =
  limpiar(data.PANTALLA);

const servicio =
  limpiar(data.SERVICIO);

const operacion =
  limpiar(data.OPERACION);

const modalidad =
  limpiar(data.MODALIDAD);

const duracion =
  limpiar(data.DURACION);

const moneda =
  limpiar(data.MONEDA);

const metodoPago =
  limpiar(data.METODO_PAGO);

const mensajeError =
  limpiar(data.MENSAJE_ERROR);

const montoSugerido =
  Number(data.MONTO_SUGERIDO || 0);

const montoRecibido =
  Number(data.MONTO_RECIBIDO || 0);


// ======================================================
// VALORES SOLO PARA MOSTRAR EN TELEGRAM
//
// IMPORTANTE:
// NO modifican SERVICIO, OPERACION ni MODALIDAD.
// Solamente eliminan "_" del texto visible para evitar
// problemas con Markdown.
//
// Ejemplo:
// CUENTA_NUEVA -> CUENTA NUEVA
// ======================================================

const servicioMostrar =
  servicio.replace(/_/g, " ");

const operacionMostrar =
  operacion.replace(/_/g, " ");

const modalidadMostrar =
  modalidad.replace(/_/g, " ");


// ======================================================
// CONTROL
// ======================================================

let textoMensaje = "";
let botones = [];


// ======================================================
// TIPO DE MOVIMIENTO
// ======================================================

if (
  pantalla === "TIPO_MOVIMIENTO"
) {

  textoMensaje =
`⚙️ *OPERACIÓN DE CAJA*

¿Qué deseas registrar?`;

  botones = teclado(

    [
      btn(
        "💰 INGRESO",
        "CAJA_TIPO_INGRESO"
      ),

      btn(
        "💸 EGRESO",
        "CAJA_TIPO_EGRESO"
      )
    ],

    [
      btn(
        "🔄 TRANSFERENCIA",
        "CAJA_TIPO_TRANSFERENCIA"
      ),

      btn(
        "🛠 AJUSTE",
        "CAJA_TIPO_AJUSTE"
      )
    ],

    [
      btn(
        "❌ CANCELAR",
        "CAJA_CANCELAR"
      )
    ]
  );
}


// ======================================================
// SERVICIO
// ======================================================

else if (
  pantalla === "SERVICIO"
) {

