// ======================================================
// NORMALIZAR VALORES
// ======================================================

function limpiar(valor, nombreCampo = "") {
  if (valor === null || valor === undefined) return "";

  let valores = Array.isArray(valor)
    ? valor.flat(Infinity)
    : [valor];

  valores = valores
    .flatMap(v =>
      String(v ?? "")
        .split(/\r?\n/)
        .map(x => x.trim())
    )
    .filter(Boolean);

  const campo = String(nombreCampo || "")
    .trim()
    .toUpperCase();

  if (campo) {
    valores = valores.filter(
      v => String(v).toUpperCase() !== campo
    );
  }

  return valores.length
    ? String(valores[valores.length - 1]).trim()
    : "";
}


// ======================================================
// CONVERTIR NÚMERO NORMAL
// ======================================================

function numeroSeguro(valor, nombreCampo = "") {

  const textoLimpio = limpiar(
    valor,
    nombreCampo
  );

  if (!textoLimpio) {
    return 0;
  }

  const numero =
    convertirMonto(textoLimpio);

  return Number.isFinite(numero)
    ? numero
    : 0;
}


// ======================================================
// CONVERTIR MONTO MANUAL
//
// ACEPTA:
//
// 7488
// 7488,32
// 7488.32
// 7.488,32
// 7,488.32
// ======================================================

function convertirMonto(valor) {

  let texto = String(valor || "")
    .trim()
    .replace(/\s/g, "");

  if (!texto) {
    return NaN;
  }

  if (!/^[0-9.,]+$/.test(texto)) {
    return NaN;
  }

  const ultimoPunto =
    texto.lastIndexOf(".");

  const ultimaComa =
    texto.lastIndexOf(",");


  if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1
  ) {

    if (ultimaComa > ultimoPunto) {

      texto = texto
        .replace(/\./g, "")
        .replace(",", ".");
    }

    else {

      texto = texto
        .replace(/,/g, "");
    }
  }

  else if (ultimaComa !== -1) {

    const partes =
      texto.split(",");

    if (
      partes.length === 2 &&
      partes[1].length <= 2
    ) {

      texto =
        partes[0] +
        "." +
        partes[1];
    }

    else {

      texto =
        texto.replace(/,/g, "");
    }
  }

  else if (ultimoPunto !== -1) {

    const partes =
      texto.split(".");

    if (
      partes.length === 2 &&
      partes[1].length <= 2
    ) {

      // Se deja como está
    }

    else {

      texto =
        texto.replace(/\./g, "");
    }
  }

  const numero =
    Number(texto);

  return Number.isFinite(numero)
    ? numero
    : NaN;
}


