const data = { ...$json };


// ======================================================
// HELPERS
// ======================================================

function limpiar(valor) {
  return String(valor ?? "").trim();
}


// ======================================================
// NORMALIZAR DATOS RECIBIDOS
// ======================================================

const tipoMovimiento =
  limpiar(
    data.TIPO_MOVIMIENTO ||
    data.TIPO ||
    ""
  );

const operacion =
  limpiar(
    data.OPERACION ||
    ""
  );

const servicio =
  limpiar(
    data.SERVICIO ||
    ""
  );

const modalidad =
  limpiar(
    data.MODALIDAD ||
    ""
  );

const duracion =
  limpiar(
    data.DURACION ||
    ""
  );

const cliente =
  limpiar(
    data.CLIENTE ||
    ""
  );

const correo =
  limpiar(
    data.CORREO ||
    ""
  );

const moneda =
  limpiar(
    data.MONEDA ||
    ""
  );

const metodoPago =
  limpiar(
    data.METODO_PAGO ||
    ""
  );

const registradoPor =
  limpiar(
    data.REGISTRADO_POR ||
    data.TELEGRAM_ID ||
    data.chat_id ||
    ""
  );

const origen =
  limpiar(
    data.ORIGEN ||
    ""
  );

const estado =
  limpiar(
    data.ESTADO ||
    ""
  );

const idOperacion =
  limpiar(
    data.ID_OPERACION ||
    data["ID OPERACION"] ||
    ""
  );


// ======================================================
// NORMALIZAR MONTOS
// ======================================================

const montoRecibido =
  Number(
    data.MONTO_RECIBIDO || 0
  );

const tasa =
  Number(
    data.TASA || 0
  );

const equivalenteUsd =
  Number(
    data.EQUIVALENTE_USD || 0
  );


// ======================================================
// FECHA / HORA VENEZUELA
// UTC -4
// ======================================================

const ahora = new Date();

const vzla = new Date(
  ahora.getTime() -
  (4 * 60 * 60 * 1000)
);

const diaNumero =
  String(
    vzla.getUTCDate()
  ).padStart(2, "0");

const mes =
  String(
    vzla.getUTCMonth() + 1
  ).padStart(2, "0");

const anio =
  vzla.getUTCFullYear();

const hora =
  String(
    vzla.getUTCHours()
  ).padStart(2, "0");

const minuto =
  String(
    vzla.getUTCMinutes()
  ).padStart(2, "0");

const segundo =
  String(
    vzla.getUTCSeconds()
  ).padStart(2, "0");


// ======================================================
// DÍA DE LA SEMANA
// ======================================================

const diasSemana = [
  "DOM",
  "LUN",
  "MAR",
  "MIER",
  "JUE",
  "VIE",
  "SAB"
];

const diaSemana =
  diasSemana[
    vzla.getUTCDay()
  ];


// ======================================================
// OBSERVACIÓN AUTOMÁTICA
// ======================================================

let observacion = "";

if (
  operacion === "CREDITO_FLUJOTV"
) {
  observacion =
    "Crédito FlujoTV registrado manualmente";
}

else if (
  tipoMovimiento === "TRANSFERENCIA"
) {
  observacion =
    "Transferencia entre cajas rápidas";
}


// ======================================================
// SALIDA PARA HISTORIAL
// ======================================================

return [
  {
    json: {

      ...data,

      ID_OPERACION:
