        duracion,

      CLIENTE:
        cliente,

      CORREO:
        correo,

      MONEDA:
        moneda,

      MONTO_RECIBIDO:
        montoRecibido,

      TASA:
        tasa,

      EQUIVALENTE_USD:
        equivalenteUsd,

      METODO_PAGO:
        metodoPago,

      REGISTRADO_POR:
        registradoPor,

      ORIGEN:
        origen,

      ESTADO:
        estado,

      OBSERVACION:
        observacion
    }
  }
];

const data =
  $('CODE - Preparar Historial')
    .first()
    .json;


// ======================================================
// FILA WEEK TRAÍDA POR GOOGLE SHEETS
// ======================================================

const itemsWeek =
  $input.all();

if (!itemsWeek.length) {

  throw new Error(
    JSON.stringify({
      error:
        "WEEK_SIN_FILA"
    })
  );
}

const filaWeek =
  itemsWeek[0].json;


// ======================================================
// DATOS DE LA OPERACIÓN
// ======================================================

const servicio =
  String(
    data.SERVICIO || ""
  )
    .trim()
    .toUpperCase();


const modalidad =
  String(
    data.MODALIDAD || ""
  )
    .trim()
    .toUpperCase();


const duracion =
  Number(
    data.DURACION || 0
  );


// ======================================================
// VALIDAR DURACIÓN
// ======================================================

if (
  !Number.isFinite(duracion) ||
  duracion <= 0
) {

  throw new Error(
    JSON.stringify({
      error:
        "DURACION_WEEK_INVALIDA",

      DURACION:
        data.DURACION
    })
  );
}


// ======================================================
// ELEGIR COLUMNA WEEK
//
// WEEK_NETFLIX_PERFIL
// WEEK_NETFLIX_COMPLETA
// WEEK_FLUJOTV_PERFIL
// WEEK_FLUJOTV_COMPLETA
// ======================================================

let columnaWeek = "";

if (
  servicio === "NETFLIX" &&
  modalidad === "PERFIL"
) {

  columnaWeek =
    "WEEK_NETFLIX_PERFIL";
}

else if (
  servicio === "NETFLIX" &&
  modalidad === "COMPLETA"
) {

  columnaWeek =
    "WEEK_NETFLIX_COMPLETA";
}

else if (
  servicio === "FLUJOTV" &&
  modalidad === "PERFIL"
) {

  columnaWeek =
    "WEEK_FLUJOTV_PERFIL";
}

else if (
  servicio === "FLUJOTV" &&
  modalidad === "COMPLETA"
) {

  columnaWeek =
    "WEEK_FLUJOTV_COMPLETA";
}

else {

  throw new Error(
    JSON.stringify({
      error:
        "COLUMNA_WEEK_NO_RECONOCIDA",

      servicio,

      modalidad
    })
  );
}


// ======================================================
// LEER VALOR ACTUAL
// ======================================================

const valorCrudo =
  filaWeek[columnaWeek];


const valorActual =
  Number(
    String(
      valorCrudo ?? "0"
    )
      .trim()
      .replace(",", ".")
  );


if (
  !Number.isFinite(valorActual)
) {

  throw new Error(
    JSON.stringify({
      error:
        "VALOR_WEEK_INVALIDO",

      columnaWeek,

      valorCrudo
    })
  );
}


// ======================================================
// SUMAR DURACIÓN
//
// Ejemplo:
// actual = 2
// duracion = 3
// nuevo = 5
// ======================================================

const nuevoValor =
  valorActual +
  duracion;


// ======================================================
// VALIDAR ROW NUMBER
// ======================================================

const rowNumberWeek =
  Number(
    filaWeek.row_number || 0
  );


if (
  !Number.isFinite(rowNumberWeek) ||
  rowNumberWeek <= 0
) {

  throw new Error(
    JSON.stringify({
      error:
        "ROW_NUMBER_WEEK_INVALIDO",

      row_number:
        filaWeek.row_number
    })
  );
}


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      ...data,

      ROW_NUMBER_WEEK:
        rowNumberWeek,

      DIA_WEEK:
        String(
          filaWeek.WEEK_DIA || ""
        ).trim(),

      COLUMNA_WEEK:
        columnaWeek,

      VALOR_WEEK_ACTUAL:
        valorActual,

      SUMAR_WEEK:
        duracion,

      NUEVO_VALOR_WEEK:
        nuevoValor
    }
  }
];

const data =
  $('CODE - Preparar Historial')
    .first()
    .json;


// ======================================================
// FILAS DE LA HOJA CAJA
// ======================================================

const filas =
  $input.all()
    .map(item => item.json);


// ======================================================
// DATOS DE LA OPERACIÓN
// ======================================================

const metodoPago =
  String(
    data.METODO_PAGO || ""
  )
    .trim()
    .toUpperCase();


// ======================================================
// NORMALIZAR MONTO RECIBIDO
//
// Acepta:
// 3746.12
// 3746,12
// 3.746,12
//
// ======================================================

let montoTexto =
  String(
    data.MONTO_RECIBIDO ?? "0"
  )
    .trim()
    .replace(/[^\d.,-]/g, "");


if (
  montoTexto.includes(".") &&
  montoTexto.includes(",")
) {

  montoTexto =
    montoTexto
      .replace(/\./g, "")
      .replace(",", ".");
}

else if (
  montoTexto.includes(",")
) {

  montoTexto =
    montoTexto.replace(",", ".");
}


const montoRecibido =
  Number(
    montoTexto || 0
  );


// ======================================================
// VALIDAR MONTO
// ======================================================

if (
  !Number.isFinite(montoRecibido) ||
  montoRecibido <= 0
) {

  throw new Error(
    JSON.stringify({
      error:
        "MONTO_CAJA_RAPIDA_INVALIDO",

      MONTO_RECIBIDO:
        data.MONTO_RECIBIDO
    })
  );
}


// ======================================================
// CONFIGURACIÓN DE CELDAS
//
// A = WEEK_DIA
// B = WEEK_NETFLIX_PERFIL
//
// PAGO MOVIL → A19
//
// ZELLE → B19
// B19:B20 está fusionada.
// El valor real está en B19.
//
// BINANCE → A22
//
// A20 NO SE TOCA.
// ======================================================

let filaObjetivo = 0;
let columnaObjetivo = "";
let cuentaCaja = "";


// ======================================================
// PAGO MÓVIL
// ======================================================

if (
  metodoPago === "PAGO_MOVIL"
) {

  filaObjetivo = 19;

  columnaObjetivo =
    "WEEK_DIA";

  cuentaCaja =
    "BOLIVARES";
}


// ======================================================
// ZELLE
// ======================================================

else if (
  metodoPago === "ZELLE"
) {

  filaObjetivo = 19;

  columnaObjetivo =
    "WEEK_NETFLIX_PERFIL";

  cuentaCaja =
    "ZELLE";
}


// ======================================================
// BINANCE
// ======================================================

else if (
  metodoPago === "BINANCE"
) {

  filaObjetivo = 22;

  columnaObjetivo =
    "WEEK_DIA";

  cuentaCaja =
    "BINANCE";
}


// ======================================================
// MÉTODO NO RECONOCIDO
// ======================================================

else {

  throw new Error(
    JSON.stringify({
      error:
        "METODO_CAJA_RAPIDA_NO_RECONOCIDO",

      metodoPago
    })
  );
}


// ======================================================
// ENCONTRAR FILA CORRECTA
// ======================================================

const fila =
  filas.find(
    row =>
      Number(
        row.row_number
      ) ===
      filaObjetivo
  );


if (!fila) {

  throw new Error(
    JSON.stringify({
      error:
        "FILA_CAJA_RAPIDA_NO_ENCONTRADA",

      filaObjetivo,

      metodoPago
    })
  );
}


// ======================================================
// LEER SALDO ACTUAL
// ======================================================

const valorCrudo =
  fila[columnaObjetivo];


// ======================================================
// NORMALIZAR SALDO ACTUAL
//
// Ejemplos:
//
// Bs15.447,20
// $16,00
// 15447
// 15447,20
// 15447.20
//
// ======================================================

let texto =
  String(
    valorCrudo ?? "0"
  )
    .trim()
    .replace(
      /[^\d.,-]/g,
      ""
    );


// ======================================================
// FORMATO:
// 15.447,20
// → 15447.20
// ======================================================

if (
  texto.includes(".") &&
  texto.includes(",")
) {

  texto =
    texto
      .replace(/\./g, "")
      .replace(",", ".");
}


// ======================================================
// FORMATO:
// 15447,20
// → 15447.20
// ======================================================

else if (
  texto.includes(",")
) {

  texto =
    texto.replace(",", ".");
}


// ======================================================
// CONVERTIR A NÚMERO
// ======================================================

const saldoActual =
  Number(
    texto || 0
  );


if (
  !Number.isFinite(saldoActual)
) {

  throw new Error(
    JSON.stringify({
      error:
        "SALDO_CAJA_RAPIDA_INVALIDO",

      cuentaCaja,

      valorCrudo,

      texto
    })
  );
}


// ======================================================
// SUMAR
//
// Internamente:
//
// 15447.20
// +
// 3746.12
// =
// 19193.32
// ======================================================

const nuevoSaldoNumero =
  Number(
    (
      saldoActual +
      montoRecibido
    ).toFixed(2)
  );


// ======================================================
// FORMATO FINAL PARA SHEETS
//
// 19193.32
// → "19193,32"
//
// No mandamos:
// 19.193,32
//
// El punto de miles lo pone la celda.
// ======================================================

const nuevoSaldo =
  nuevoSaldoNumero
    .toFixed(2)
    .replace(".", ",");


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      ...data,

      CUENTA_CAJA_RAPIDA:
        cuentaCaja,

      ROW_NUMBER_CAJA_RAPIDA:
        filaObjetivo,

      COLUMNA_CAJA_RAPIDA:
        columnaObjetivo,

      SALDO_ACTUAL_CAJA_RAPIDA:
        saldoActual,

      MONTO_A_SUMAR:
        montoRecibido,

      NUEVO_SALDO_CAJA_RAPIDA:
        nuevoSaldo
    }
  }
];

