parameters.jsCode:
// ======================================================
// ENTRADA
//
// IMPORTANTE:
// Este nodo recibe el item actual.
//
// Funciona con:
//
// - Cuenta nueva automática
// - Renovación automática normal
// - Renovación automática agrupada de 1 servicio
// - Renovación automática múltiple
//
// Conserva cálculos previos:
// MONTO_SUGERIDO
// TASA
// DETALLE_OPERACION
// TOTAL_RENOVACIONES_USD
// etc.
// ======================================================

const entrada = {
  ...$json
};


// ======================================================
// HELPERS
// ======================================================

function limpiar(valor) {
  return String(
    valor ?? ""
  ).trim();
}


function mayus(valor) {
  return limpiar(valor)
    .toUpperCase();
}


function numero(valor) {

  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {
    return 0;
  }


  if (
    typeof valor === "number"
  ) {

    return Number.isFinite(valor)
      ? valor
      : 0;
  }


  let texto =
    String(valor)
      .trim()
      .replace(/\$/g, "")
      .replace(/USD/gi, "")
      .replace(/USDT/gi, "")
      .replace(/\s/g, "");


  const ultimoPunto =
    texto.lastIndexOf(".");

  const ultimaComa =
    texto.lastIndexOf(",");


  // 1.234,50
  if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1 &&
    ultimaComa > ultimoPunto
  ) {

    texto =
      texto
        .replace(/\./g, "")
        .replace(",", ".");
  }


  // 1,234.50
  else if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1 &&
    ultimoPunto > ultimaComa
  ) {

    texto =
      texto.replace(/,/g, "");
  }


  // 1234,50
  else if (
    ultimaComa !== -1
  ) {

    texto =
      texto.replace(",", ".");
  }


  const n =
    Number(texto);


  return Number.isFinite(n)
    ? n
    : 0;
}


// ======================================================
// DATOS RECIBIDOS
// ======================================================

const telegramId =
  limpiar(
    entrada.TELEGRAM_ID ||
    entrada.chat_id ||
    ""
  );


const mensaje =
  mayus(
    entrada.MENSAJE_TELEGRAM ||
    ""
  );


const servicio =
  mayus(
    entrada.SERVICIO ||
    ""
  );


const modalidad =
  mayus(
    entrada.MODALIDAD ||
    ""
  );


const duracion =
  numero(
    entrada.DURACION ||
    0
  );


const cliente =
  limpiar(
    entrada.CLIENTE ||
    ""
  );


const correo =
  limpiar(
    entrada.CORREO ||
    ""
  );


const operacion =
  mayus(
    entrada.OPERACION ||
    ""
  );


const origen =
  mayus(
    entrada.ORIGEN ||
    "AUTOMATICO"
  );


// ======================================================
// DETALLE OPERACIÓN
// ======================================================

const detalleOperacion =
  Array.isArray(
    entrada.DETALLE_OPERACION
  )
    ? entrada.DETALLE_OPERACION
    : [];


// ======================================================
// TOTALES RENOVACIÓN
// ======================================================

const totalRenovaciones =
  numero(
    entrada.TOTAL_RENOVACIONES ||
    detalleOperacion.length ||
    0
  );


const totalNetflix =
  numero(
    entrada.TOTAL_NETFLIX ||
    0
  );


const totalFlujoTV =
  numero(
    entrada.TOTAL_FLUJOTV ||
    0
  );


const totalRenovacionesUsd =
  numero(
    entrada.TOTAL_RENOVACIONES_USD ||
    entrada.EQUIVALENTE_USD ||
    0
  );


// ======================================================
// MONTOS YA CALCULADOS
// ======================================================

const montoSugerido =
  numero(
    entrada.MONTO_SUGERIDO ||
    0
  );


const montoRecibido =
  numero(
    entrada.MONTO_RECIBIDO ||
    0
  );


const tasa =
  numero(
    entrada.TASA ||
    0
  );


const equivalenteUsd =
  numero(
    entrada.EQUIVALENTE_USD ||
    entrada.TOTAL_RENOVACIONES_USD ||
    0
  );


// ======================================================
// MÉTODO / MONEDA
// ======================================================

const moneda =
  mayus(
    entrada.MONEDA ||
    ""
  );


const metodoPago =
  mayus(
    entrada.METODO_PAGO ||
    ""
  );


// ======================================================
// REGISTRADO POR
// ======================================================

let registradoPor =
  limpiar(
    entrada.REGISTRADO_POR ||
    ""
  );


if (
  !registradoPor
) {

  if (
    telegramId === "1057242322"
  ) {

    registradoPor =
      "GABRIEL";
  }


  else if (
    telegramId === "941030473"
  ) {

    registradoPor =
      "EDWARD";
  }


  else {

    registradoPor =
      telegramId;
  }
}


// ======================================================
// TIPO DE FLUJO
//
// MUY IMPORTANTE:
//
// MENSAJE_TELEGRAM puede llamarse:
// AUTO_CAJA_RENOVACION_MULTIPLE
//
// aunque el agrupador tenga solamente 1 renovación.
//
// Por eso NO usamos MENSAJE_TELEGRAM para decidir
// si realmente es múltiple.
//
// La multiplicidad real depende de:
//
// - OPERACION = RENOVACION_MULTIPLE
// - DETALLE_OPERACION tiene más de 1
// - TOTAL_RENOVACIONES > 1
// ======================================================

const esRenovacionMultiple =
  operacion ===
    "RENOVACION_MULTIPLE"
  ||
  detalleOperacion.length > 1
  ||
  totalRenovaciones > 1;


// ======================================================
// RENOVACIÓN AUTOMÁTICA
//
// Aquí sí podemos usar el mensaje para saber
// que pertenece al sistema automático.
// ======================================================

const esRenovacionAutomatica =
  mensaje ===
    "AUTO_CAJA_RENOVACION"
  ||
  mensaje ===
    "AUTO_CAJA_RENOVACION_MULTIPLE"
  ||
  operacion ===
    "RENOVACION"
  ||
  operacion ===
    "RENOVACION_MULTIPLE";


// ======================================================
// CUENTA NUEVA AUTOMÁTICA
// ======================================================

const esCuentaNuevaAutomatica =
  mensaje ===
    "AUTO_CAJA_CUENTA_NUEVA"
  ||
  operacion ===
    "NUEVA"
  ||
  operacion ===
    "CUENTA_NUEVA";


// ======================================================
// VALIDACIONES GENERALES
// ======================================================

if (
  !telegramId
) {

  throw new Error(
    JSON.stringify({
      error:
        "AUTO_CAJA_TELEGRAM_ID_VACIO"
    })
  );
}


// ======================================================
// VALIDAR MENSAJE
// ======================================================

if (
  mensaje !==
    "AUTO_CAJA_RENOVACION" &&
  mensaje !==
    "AUTO_CAJA_CUENTA_NUEVA" &&
  mensaje !==
    "AUTO_CAJA_RENOVACION_MULTIPLE"
) {

  throw new Error(
    JSON.stringify({
      error:
        "AUTO_CAJA_MENSAJE_INVALIDO",

      mensaje
    })
  );
}


// ======================================================
// VALIDAR RENOVACIÓN MÚLTIPLE
// ======================================================

if (
  esRenovacionMultiple
) {

  if (
    !detalleOperacion.length
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "AUTO_CAJA_MULTIPLE_SIN_DETALLE"
      })
    );
  }


  if (
    totalRenovaciones <= 1
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "AUTO_CAJA_TOTAL_RENOVACIONES_MULTIPLE_INVALIDO",

        TOTAL_RENOVACIONES:
          entrada.TOTAL_RENOVACIONES,

        DETALLE:
          detalleOperacion.length
      })
    );
  }


  if (
    montoSugerido <= 0
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "AUTO_CAJA_MULTIPLE_MONTO_INVALIDO",

        MONTO_SUGERIDO:
          entrada.MONTO_SUGERIDO,

        TOTAL_RENOVACIONES_USD:
          entrada.TOTAL_RENOVACIONES_USD
      })
    );
  }


  if (
    tasa <= 0
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "AUTO_CAJA_MULTIPLE_TASA_INVALIDA",

        TASA:
          entrada.TASA
      })
    );
  }
}


// ======================================================
// VALIDAR FLUJO DE UNA SOLA OPERACIÓN
//
// También aplica cuando:
// MENSAJE_TELEGRAM = AUTO_CAJA_RENOVACION_MULTIPLE
//
// pero DETALLE_OPERACION solamente tiene 1 renovación.
// ======================================================

else {

  if (
    servicio !== "NETFLIX" &&
    servicio !== "FLUJOTV"
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "AUTO_CAJA_SERVICIO_INVALIDO",

        servicio
      })
    );
  }


  if (
    modalidad !== "PERFIL" &&
    modalidad !== "COMPLETA"
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "AUTO_CAJA_MODALIDAD_INVALIDA",

        modalidad
      })
    );
  }


  if (
    !Number.isFinite(duracion) ||
    duracion <= 0
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "AUTO_CAJA_DURACION_INVALIDA",

        DURACION:
          entrada.DURACION
      })
    );
  }


  // ----------------------------------------------------
  // Si viene del agrupador, puede tener exactamente
  // 1 renovación y ya venir calculada.
  // ----------------------------------------------------

  if (
    esRenovacionAutomatica &&
    detalleOperacion.length === 1
  ) {

    if (
      montoSugerido <= 0
    ) {

      throw new Error(
        JSON.stringify({
          error:
            "AUTO_CAJA_RENOVACION_MONTO_INVALIDO",

          MONTO_SUGERIDO:
            entrada.MONTO_SUGERIDO,

          TOTAL_RENOVACIONES_USD:
            entrada.TOTAL_RENOVACIONES_USD
        })
      );
    }


    if (
      tasa <= 0
    ) {

      throw new Error(
        JSON.stringify({
          error:
            "AUTO_CAJA_RENOVACION_TASA_INVALIDA",

          TASA:
            entrada.TASA
        })
      );
    }
  }
}


// ======================================================
// ID OPERACIÓN
//
// Si ya viene uno,
// lo conservamos.
//
// Si no,
// creamos uno.
// ======================================================

const idOperacion =
  limpiar(
    entrada.ID_OPERACION
  )
  ||
  `OP_${telegramId}_${Date.now()}`;


// ======================================================
// VALORES PRINCIPALES
//
// UNA RENOVACIÓN:
//
// SERVICIO = NETFLIX / FLUJOTV
// MODALIDAD = PERFIL / COMPLETA
// DURACION = duración real
// OPERACION = RENOVACION
//
// VARIAS:
//
// SERVICIO = MULTIPLE
// MODALIDAD = MULTIPLE
// DURACION = cantidad de renovaciones
// OPERACION = RENOVACION_MULTIPLE
// ======================================================

let servicioFinal =
  servicio;

let modalidadFinal =
  modalidad;

let duracionFinal =
  duracion;

let operacionFinal =
  operacion;


// ======================================================
// SOLAMENTE CONVERTIR A MULTIPLE
// CUANDO REALMENTE HAYA MÁS DE UNA.
// ======================================================

if (
  esRenovacionMultiple
) {

  servicioFinal =
    "MULTIPLE";

  modalidadFinal =
    "MULTIPLE";

  duracionFinal =
    totalRenovaciones;

  operacionFinal =
    "RENOVACION_MULTIPLE";
}


// ======================================================
// SI SOLAMENTE HAY UNA RENOVACIÓN DEL AGRUPADOR
//
// La dejamos explícitamente como RENOVACION.
// ======================================================

else if (
  esRenovacionAutomatica &&
  detalleOperacion.length === 1
) {

  const unica =
    detalleOperacion[0];


  servicioFinal =
    mayus(
      unica.SERVICIO ||
      servicio
    );


  modalidadFinal =
    mayus(
      unica.MODALIDAD ||
      modalidad
    );


  duracionFinal =
    numero(
      unica.DURACION ||
      duracion
    );


  operacionFinal =
    "RENOVACION";
}


// ======================================================
// CORREO
//
// En las renovaciones provenientes del agrupador,
// CODE - Calcular monto multiple convierte
// DETALLE_OPERACION a JSON y lo coloca temporalmente
// dentro de CORREO.
//
// NO lo tocamos aquí.
// ======================================================

const correoFinal =
  correo;


// ======================================================
// SALIDA
//
// Primera entrada automática:
//
// MESSAGE_ID = ""
//
// Después:
//
// Enviar método de pago
// → Telegram devuelve message_id
// → Update LOGS_CAJA guarda el ID real.
// ======================================================

return [
  {
    json: {

      // -----------------------------------------------
      // CONSERVAR TODO
      // -----------------------------------------------

      ...entrada,


      // -----------------------------------------------
      // IDENTIDAD
      // -----------------------------------------------

      ID_OPERACION:
        idOperacion,

      TELEGRAM_ID:
        telegramId,

      chat_id:
        telegramId,

      MESSAGE_ID:
        "",


      // -----------------------------------------------
      // ESTADO
      // -----------------------------------------------

      ESTADO:
        "ESPERA_METODO_PAGO",

      TIPO_MOVIMIENTO:
        "INGRESO",


      // -----------------------------------------------
      // OPERACIÓN
      // -----------------------------------------------

      OPERACION:
        operacionFinal,

      SERVICIO:
        servicioFinal,

      MODALIDAD:
        modalidadFinal,

      DURACION:
        duracionFinal,


      // -----------------------------------------------
      // CLIENTE
      // -----------------------------------------------

      CLIENTE:
        cliente,

      CORREO:
        correoFinal,


      // -----------------------------------------------
      // DINERO
      //
      // NO borramos cálculos previos.
      // -----------------------------------------------

      MONEDA:
        moneda,

      MONTO_SUGERIDO:
        montoSugerido,

      MONTO_RECIBIDO:
        montoRecibido,

      TASA:
        tasa,

      EQUIVALENTE_USD:
        equivalenteUsd,

      METODO_PAGO:
        metodoPago,


      // -----------------------------------------------
      // RESPONSABLE / ORIGEN
      // -----------------------------------------------

      REGISTRADO_POR:
        registradoPor,

      ORIGEN:
        origen || "AUTOMATICO",


      // -----------------------------------------------
      // FECHA
      // -----------------------------------------------

      FECHA_CREACION:
        limpiar(
          entrada.FECHA_CREACION
        )
        ||
        new Date().toISOString(),


      // -----------------------------------------------
      // PANTALLA
      // -----------------------------------------------

      PANTALLA:
        "METODO_PAGO",

      ACCION_SISTEMA:
        "CONTINUAR",

      ES_AUTO:
        true,

      MENSAJE_TELEGRAM:
        mensaje,


      // -----------------------------------------------
      // DATOS DE RENOVACIONES
      // -----------------------------------------------

      TOTAL_RENOVACIONES:
        totalRenovaciones,

      TOTAL_NETFLIX:
        totalNetflix,

      TOTAL_FLUJOTV:
        totalFlujoTV,

      TOTAL_RENOVACIONES_USD:
        totalRenovacionesUsd,

      DETALLE_OPERACION:
        detalleOperacion,


      // -----------------------------------------------
      // BANDERAS
      // -----------------------------------------------

      ES_RENOVACION_AUTOMATICA:
        esRenovacionAutomatica,

      ES_RENOVACION_MULTIPLE:
        esRenovacionMultiple,

      ES_CUENTA_NUEVA_AUTOMATICA:
        esCuentaNuevaAutomatica
    }
  }
];

