={{
  (() => {

    const data =
      $('CODE - Preparar Caja Automatica')
        .first()
        .json;


    const detalle =
      Array.isArray(data.DETALLE_OPERACION)
        ? data.DETALLE_OPERACION
        : [];


    const formatoMonto = (valor) =>
      Number(valor || 0)
        .toLocaleString(
          "es-VE",
          {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
          }
        );


    // ==================================================
    // TEXTO DEL MENSAJE
    // ==================================================

    let texto = "";


    // ==================================================
    // RENOVACIÓN AUTOMÁTICA
    //
    // Puede ser:
    // - 1 renovación
    // - varias renovaciones
    // ==================================================

    if (
      detalle.length > 0
    ) {

      const cantidad =
        Number(
          data.TOTAL_RENOVACIONES ||
          detalle.length
        );


      const totalUsd =
        Number(
          data.TOTAL_RENOVACIONES_USD ||
          data.MONTO_SUGERIDO ||
          data.EQUIVALENTE_USD ||
          0
        );


      const cliente =
        String(
          data.CLIENTE || ""
        );


      const lineas =
        detalle
          .map((item, index) => {

            const servicio =
              String(
                item.SERVICIO || ""
              )
                .replace(/_/g, " ");


            const modalidad =
              String(
                item.MODALIDAD || ""
              )
                .replace(/_/g, " ");


            const duracion =
              Number(
                item.DURACION || 0
              );


            const correo =
              String(
                item.CORREO || ""
              );


            const subtotal =
              Number(
                item.SUBTOTAL_USD || 0
              );


            const palabra =
              duracion === 1
                ? "mes"
                : "meses";


            let linea =
              `${index + 1}. *${servicio}* · ${modalidad} · ${duracion} ${palabra}`;


            if (
              subtotal > 0
            ) {

              linea +=
                ` · $${formatoMonto(subtotal)}`;
            }


            if (
              correo
            ) {

              linea +=
                `\n   📧 ${correo}`;
            }


            return linea;
          })
          .join("\n\n");


      texto =
        `💰 *COBRO DE RENOVACIÓN*\n\n`
        + `Cliente: *${cliente}*\n`
        + `Renovaciones: *${cantidad}*\n\n`
        + `${lineas}\n\n`
        + `💵 Total: *$${formatoMonto(totalUsd)}*\n\n`
        + `*¿Cómo te pagaron?*`;
    }


    // ==================================================
    // CUENTA NUEVA / AUTOMÁTICO NORMAL
    // ==================================================

    else {

      const servicio =
        String(
          data.SERVICIO || ""
        )
          .replace(/_/g, " ");


      const modalidad =
        String(
          data.MODALIDAD || ""
        )
          .replace(/_/g, " ");


      texto =
        `💰 *REGISTRAR INGRESO*\n\n`
        + `*Servicio:* ${servicio}\n`
        + `*Modalidad:* ${modalidad}\n`
        + `*Duración:* ${data.DURACION} mes(es)\n`
        + `*Cliente:* ${data.CLIENTE || ""}\n`
        + `*Correo:* ${data.CORREO || ""}\n\n`
        + `*¿Cómo te pagaron?*`;
    }


    // ==================================================
    // BODY TELEGRAM
    // ==================================================

    return {

      chat_id:
        "-1004294140271",

      text:
        texto,

      parse_mode:
        "Markdown",

      reply_markup: {

        inline_keyboard: [

          [
            {
              text:
                "📱 PAGO MÓVIL",

              callback_data:
                "CAJA_PAGO_PAGO_MOVIL"
            }
          ],

          [
            {
              text:
                "💵 ZELLE",

              callback_data:
                "CAJA_PAGO_ZELLE"
            }
          ],

          [
            {
              text:
                "🟡 BINANCE",

              callback_data:
                "CAJA_PAGO_BINANCE"
            }
          ],

          [
            {
              text:
                "❌ CANCELAR",

              callback_data:
                "CAJA_CANCELAR"
            }
          ]
        ]
      }
    };

  })()
}}

