const data = { ...$json };


// ======================================================
// CONFIGURACIÓN
// ======================================================

// Precio FIJO de cada crédito FlujoTV.
// No cambia.
const PRECIO_CREDITO_USD = 3.5;


// ======================================================
// USUARIOS
// ======================================================
//
// Identificamos quién está realizando la operación
// usando su TELEGRAM_ID personal.
//
// Esto permitirá después separar en el cierre:
//
// GABRIEL:
// - Bs
// - Zelle
// - Binance
//
// EDWARD:
// - Bs
// - Zelle
// - Binance
//
// ======================================================

const USUARIOS = {
  "1057242322": "GABRIEL",
  "941030473": "EDWARD"
};


// ======================================================
// HELPERS
// ======================================================

function limpiar(valor) {
  return String(valor ?? "").trim();
}


// ======================================================
// DATOS ACTUALES
// ======================================================

const accion =
  limpiar(
    data.ACCION_CAJA ||
    data.MENSAJE_TELEGRAM ||
    ""
  );

const estadoActual =
  limpiar(
    data.ESTADO ||
    data.ESTADO_ACTUAL ||
    ""
  );

const telegramId =
  limpiar(
    data.TELEGRAM_ID ||
    data.chat_id ||
    ""
  );

const idOperacion =
  limpiar(
    data.ID_OPERACION ||
    data["ID OPERACION"] ||
    ""
  );

const messageId =
  limpiar(
    data.MESSAGE_ID ||
    ""
  );


// ======================================================
// REGISTRADO POR
// ======================================================
//
// Siempre lo resolvemos desde TELEGRAM_ID.
// No dependemos de que venga guardado previamente.
//
// ======================================================

const registradoPor =
  USUARIOS[telegramId] ||
  limpiar(data.REGISTRADO_POR) ||
  "DESCONOCIDO";


// ======================================================
// VALORES DE LA OPERACIÓN
// ======================================================

let estado =
  estadoActual;

let pantalla = "";

let accionSistema =
  "CONTINUAR";

let mensajeError = "";

let moneda =
  limpiar(
    data.MONEDA ||
    ""
  );

let metodoPago =
  limpiar(
    data.METODO_PAGO ||
    ""
  );


// DURACION representa la CANTIDAD DE CRÉDITOS.
// Esto permite reutilizar WEEK:
//
// FLUJOTV + COMPLETA + DURACION
//
// = suma exactamente la cantidad de créditos.

let cantidadCreditos =
  Number(
    data.DURACION ||
    data.CANTIDAD_CREDITOS ||
    0
  );

if (
  !Number.isFinite(cantidadCreditos) ||
  cantidadCreditos < 0
) {
  cantidadCreditos = 0;
}


let totalUsd =
  Number(
    data.TOTAL_CREDITOS_USD ||
    0
  );


let montoSugerido =
  Number(
    data.MONTO_SUGERIDO ||
    0
  );


let montoRecibido =
  Number(
    data.MONTO_RECIBIDO ||
    0
  );


let tasa =
  Number(
    data.TASA ||
    0
  );


// ======================================================
// VALIDACIONES BASE
// ======================================================

if (!telegramId) {

  throw new Error(
    JSON.stringify({
      error:
        "CREDITO_FLUJOTV_TELEGRAM_ID_VACIO",

      accion
    })
  );
}


if (!idOperacion) {

  throw new Error(
    JSON.stringify({
      error:
        "CREDITO_FLUJOTV_ID_OPERACION_VACIO",

      telegramId,

      accion
    })
  );
}


// ======================================================
// CANCELAR
// ======================================================

if (
  accion === "CAJA_CANCELAR"
) {

  estado =
    "CANCELADO";

  pantalla =
    "CANCELADO";

  accionSistema =
    "CANCELAR";

  montoSugerido = 0;
  montoRecibido = 0;
}


// ======================================================
// INICIAR CRÉDITO FLUJOTV
//
// Primero elegimos CANTIDAD,
// NO método de pago.
// ======================================================

else if (
  accion === "CAJA_TIPO_DIRECTO"
) {

  cantidadCreditos = 0;

  totalUsd = 0;

  moneda = "";
  metodoPago = "";

  montoSugerido = 0;
  montoRecibido = 0;

  tasa = 0;

  estado =
    "ESPERA_CANTIDAD_CREDITO";

  pantalla =
    "CANTIDAD_CREDITO";

  accionSistema =
    "CONTINUAR";
}


// ======================================================
// CANTIDADES RÁPIDAS
//
// Callbacks esperados:
//
// CAJA_CREDITO_CANTIDAD_1
// CAJA_CREDITO_CANTIDAD_2
// CAJA_CREDITO_CANTIDAD_3
// CAJA_CREDITO_CANTIDAD_5
// CAJA_CREDITO_CANTIDAD_10
//
// ======================================================

else if (
  accion.startsWith(
    "CAJA_CREDITO_CANTIDAD_"
  ) &&
  accion !==
    "CAJA_CREDITO_CANTIDAD_MANUAL"
) {

  const cantidadTexto =
    accion.replace(
      "CAJA_CREDITO_CANTIDAD_",
      ""
    );

  const cantidad =
    Number(
      cantidadTexto
    );

  if (
    !Number.isInteger(cantidad) ||
    cantidad < 1
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "CANTIDAD_CREDITO_INVALIDA",

        accion,

        cantidadTexto
      })
    );
  }

  cantidadCreditos =
    cantidad;

  totalUsd =
    Number(
      (
        cantidadCreditos *
        PRECIO_CREDITO_USD
      ).toFixed(2)
    );

  moneda = "";
  metodoPago = "";

  montoSugerido = 0;
  montoRecibido = 0;

  tasa = 0;

  estado =
    "ESPERA_METODO_PAGO_CREDITO";

  pantalla =
    "METODO_PAGO_CREDITO";

  accionSistema =
    "CONTINUAR";
}


// ======================================================
// CANTIDAD MANUAL
// PEDIR TEXTO
// ======================================================

else if (
  accion ===
  "CAJA_CREDITO_CANTIDAD_MANUAL"
) {

  cantidadCreditos = 0;

  totalUsd = 0;

  moneda = "";
  metodoPago = "";

  montoSugerido = 0;
  montoRecibido = 0;

  tasa = 0;

  estado =
    "ESPERA_CANTIDAD_CREDITO_MANUAL";

  pantalla =
    "CANTIDAD_CREDITO_MANUAL";

  accionSistema =
    "ESPERAR_TEXTO";
}


// ======================================================
// CANTIDAD MANUAL
// VALIDAR TEXTO
// ======================================================

else if (
  estadoActual ===
  "ESPERA_CANTIDAD_CREDITO_MANUAL"
) {

  const texto =
    limpiar(
      data.MENSAJE_TELEGRAM ||
      accion
    );

  // Solo números enteros.
  if (
    !/^\d+$/.test(texto)
  ) {

    estado =
      "ESPERA_CANTIDAD_CREDITO_MANUAL";

    pantalla =
      "CANTIDAD_CREDITO_MANUAL_ERROR";

    accionSistema =
      "ESPERAR_TEXTO";

    mensajeError =
      "Escribe solamente una cantidad entera de créditos.";
  }

  else {

    const cantidad =
      Number(texto);

    if (
      !Number.isInteger(cantidad) ||
      cantidad < 1 ||
      cantidad > 1000
    ) {

      estado =
        "ESPERA_CANTIDAD_CREDITO_MANUAL";

      pantalla =
        "CANTIDAD_CREDITO_MANUAL_ERROR";

      accionSistema =
        "ESPERAR_TEXTO";

      mensajeError =
        "Ingresa una cantidad válida de créditos.";
    }

    else {

      cantidadCreditos =
        cantidad;

      totalUsd =
        Number(
          (
            cantidadCreditos *
            PRECIO_CREDITO_USD
          ).toFixed(2)
        );

      moneda = "";
      metodoPago = "";

      montoSugerido = 0;
      montoRecibido = 0;

      tasa = 0;

      estado =
        "ESPERA_METODO_PAGO_CREDITO";

      pantalla =
        "METODO_PAGO_CREDITO";

      accionSistema =
        "CONTINUAR";
    }
  }
}


// ======================================================
// PAGO MÓVIL
//
// NO pedimos monto.
// Mandamos a calcular automáticamente.
// ======================================================

else if (
  accion ===
  "CAJA_CREDITO_PAGO_MOVIL"
) {

  if (
    !Number.isInteger(cantidadCreditos) ||
    cantidadCreditos < 1
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "CREDITO_SIN_CANTIDAD",

        cantidadCreditos
      })
    );
  }

  metodoPago =
    "PAGO_MOVIL";

  moneda =
    "BS";

  totalUsd =
    Number(
      (
        cantidadCreditos *
        PRECIO_CREDITO_USD
      ).toFixed(2)
    );

  montoSugerido = 0;
  montoRecibido = 0;

  tasa = 0;

  estado =
    "ESPERA_CALCULO_CREDITO";

  pantalla =
    "CALCULAR_CREDITO";

  accionSistema =
    "CALCULAR_CREDITO";
}


// ======================================================
// ZELLE
// ======================================================

else if (
  accion ===
  "CAJA_CREDITO_ZELLE"
) {

  if (
    !Number.isInteger(cantidadCreditos) ||
    cantidadCreditos < 1
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "CREDITO_SIN_CANTIDAD",

        cantidadCreditos
      })
    );
  }

  metodoPago =
    "ZELLE";

  moneda =
    "USD";

  totalUsd =
    Number(
      (
        cantidadCreditos *
        PRECIO_CREDITO_USD
      ).toFixed(2)
    );

  montoSugerido = 0;
  montoRecibido = 0;

  tasa = 0;

  estado =
    "ESPERA_CALCULO_CREDITO";

  pantalla =
    "CALCULAR_CREDITO";

  accionSistema =
    "CALCULAR_CREDITO";
}


// ======================================================
// BINANCE
// ======================================================

else if (
  accion ===
  "CAJA_CREDITO_BINANCE"
) {

  if (
    !Number.isInteger(cantidadCreditos) ||
    cantidadCreditos < 1
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "CREDITO_SIN_CANTIDAD",

        cantidadCreditos
      })
    );
  }

  metodoPago =
    "BINANCE";

  moneda =
    "USDT";

  totalUsd =
    Number(
      (
        cantidadCreditos *
        PRECIO_CREDITO_USD
      ).toFixed(2)
    );

  montoSugerido = 0;
  montoRecibido = 0;

  tasa = 0;

  estado =
    "ESPERA_CALCULO_CREDITO";

  pantalla =
    "CALCULAR_CREDITO";

  accionSistema =
    "CALCULAR_CREDITO";
}


// ======================================================
// ATRÁS
// ======================================================

else if (
  accion === "CAJA_CREDITO_ATRAS"
) {

  // ----------------------------------------------------
  // CONFIRMACIÓN
  // → volver a método de pago
  // ----------------------------------------------------

  if (
    estadoActual ===
      "ESPERA_CONFIRMACION_CREDITO" ||
    estadoActual ===
      "ESPERA_CALCULO_CREDITO"
  ) {

    moneda = "";
    metodoPago = "";

    montoSugerido = 0;
    montoRecibido = 0;

    tasa = 0;

    estado =
      "ESPERA_METODO_PAGO_CREDITO";

    pantalla =
      "METODO_PAGO_CREDITO";

    accionSistema =
      "CONTINUAR";
  }


  // ----------------------------------------------------
  // MÉTODO DE PAGO
  // → volver a cantidad de créditos
  // ----------------------------------------------------

  else if (
    estadoActual ===
    "ESPERA_METODO_PAGO_CREDITO"
  ) {

    moneda = "";
    metodoPago = "";

    montoSugerido = 0;
    montoRecibido = 0;

    tasa = 0;

    estado =
      "ESPERA_CANTIDAD_CREDITO";

    pantalla =
      "CANTIDAD_CREDITO";

    accionSistema =
      "CONTINUAR";
  }


  // ----------------------------------------------------
  // CANTIDAD MANUAL
  // → volver a cantidades
  // ----------------------------------------------------

  else if (
    estadoActual ===
      "ESPERA_CANTIDAD_CREDITO_MANUAL" ||
    estadoActual ===
      "ESPERA_CANTIDAD_CREDITO_MANUAL_ERROR"
  ) {

    cantidadCreditos = 0;

    totalUsd = 0;

    estado =
      "ESPERA_CANTIDAD_CREDITO";

    pantalla =
      "CANTIDAD_CREDITO";

    accionSistema =
      "CONTINUAR";
  }


  // ----------------------------------------------------
  // FALLBACK
  // ----------------------------------------------------

  else {

    estado =
      "ESPERA_CANTIDAD_CREDITO";

    pantalla =
      "CANTIDAD_CREDITO";

    accionSistema =
      "CONTINUAR";
  }
}


// ======================================================
// REGISTRAR CRÉDITO DEFINITIVAMENTE
//
// DURACION = cantidad de créditos.
//
// Esto hace que WEEK sume:
//
// FLUJOTV
// COMPLETA
// + cantidadCreditos
// ======================================================

else if (
  accion ===
  "CAJA_REGISTRAR_CREDITO"
) {

  if (
    !Number.isInteger(cantidadCreditos) ||
    cantidadCreditos < 1
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "CANTIDAD_CREDITO_INVALIDA_AL_REGISTRAR",

        DURACION:
          data.DURACION
      })
    );
  }


  if (
    !Number.isFinite(montoRecibido) ||
    montoRecibido <= 0
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "MONTO_CREDITO_INVALIDO",

        MONTO_RECIBIDO:
          data.MONTO_RECIBIDO
      })
    );
  }


  estado =
    "COMPLETADO";

  pantalla =
    "CREDITO_COMPLETADO";

  accionSistema =
    "REGISTRAR_INGRESO";
}


// ======================================================
// ACCIÓN NO RECONOCIDA
// ======================================================

else {

  throw new Error(
    JSON.stringify({
      error:
        "ACCION_CREDITO_FLUJOTV_NO_RECONOCIDA",

      accion,

      estadoActual,

      telegramId,

      idOperacion
    })
  );
}


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      ...data,

      ID_OPERACION:
        idOperacion,

      TELEGRAM_ID:
        telegramId,

      chat_id:
        telegramId,

      MESSAGE_ID:
        messageId,


      // ===============================================
      // DATOS FIJOS
      // ===============================================

      TIPO_MOVIMIENTO:
        "INGRESO",

      OPERACION:
        "CREDITO_FLUJOTV",

      SERVICIO:
        "FLUJOTV",

      MODALIDAD:
        "COMPLETA",


      // ===============================================
      // CRÉDITOS
      // ===============================================

      DURACION:
        String(
          cantidadCreditos || ""
        ),

      CANTIDAD_CREDITOS:
        cantidadCreditos,

      PRECIO_CREDITO_USD:
        PRECIO_CREDITO_USD,

      TOTAL_CREDITOS_USD:
        Number(
          totalUsd.toFixed(2)
        ),


      // ===============================================
      // DINERO
      // ===============================================

      MONEDA:
        moneda,

      METODO_PAGO:
        metodoPago,

      MONTO_SUGERIDO:
        montoSugerido,

      MONTO_RECIBIDO:
        montoRecibido,

      TASA:
        tasa,

      EQUIVALENTE_USD:
        Number(
          totalUsd.toFixed(2)
        ),


      // ===============================================
      // QUIÉN REGISTRÓ LA OPERACIÓN
      // ===============================================

      REGISTRADO_POR:
        registradoPor,


      // ===============================================
      // CONTROL
      // ===============================================

      ESTADO:
        estado,

      PANTALLA:
        pantalla,

      ACCION_SISTEMA:
        accionSistema,

      MENSAJE_ERROR:
        mensajeError,

      ORIGEN:
        "MANUAL"
    }
  }
];

const data = { ...$json };


// ======================================================
// HELPERS
// ======================================================

function limpiar(valor) {
  return String(valor ?? "").trim();
}


// ======================================================
// CONVERTIR MONTO MANUAL
//
// ACEPTA:
// 7488
// 7488,32
// 7488.32
// 7.488,32
// 7,488.32
// ======================================================

function convertirMonto(valor) {

  let texto = String(valor || "")
    .trim()
    .replace(/\s/g, "");

  if (!texto) {
    return NaN;
  }

  if (!/^[0-9.,]+$/.test(texto)) {
    return NaN;
  }

  const ultimoPunto =
    texto.lastIndexOf(".");

  const ultimaComa =
    texto.lastIndexOf(",");


  // ====================================================
  // PUNTO + COMA
  // ====================================================

  if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1
  ) {

    // 7.488,32
    if (ultimaComa > ultimoPunto) {

      texto = texto
        .replace(/\./g, "")
        .replace(",", ".");
    }

    // 7,488.32
    else {

      texto =
        texto.replace(/,/g, "");
    }
  }


  // ====================================================
  // SOLO COMA
  // ====================================================

  else if (ultimaComa !== -1) {

    const partes =
      texto.split(",");

    // 7488,32
    if (
      partes.length === 2 &&
      partes[1].length <= 2
    ) {

      texto =
        partes[0] +
        "." +
        partes[1];
    }

    // 7,488
    else {

      texto =
        texto.replace(/,/g, "");
    }
  }


  // ====================================================
  // SOLO PUNTO
  // ====================================================

  else if (ultimoPunto !== -1) {

    const partes =
      texto.split(".");

    // 7488.32
    if (
      partes.length === 2 &&
      partes[1].length <= 2
    ) {

      // Se deja así
    }

    // 7.488
    else {

      texto =
        texto.replace(/\./g, "");
    }
  }


  const numero =
    Number(texto);

  return Number.isFinite(numero)
    ? numero
    : NaN;
}


// ======================================================
// DATOS ACTUALES
// ======================================================

const accion =
  limpiar(
    data.ACCION_CAJA ||
    data.MENSAJE_TELEGRAM ||
    ""
  );

const estadoActual =
  limpiar(
    data.ESTADO ||
    data.ESTADO_ACTUAL ||
    ""
  );

const telegramId =
