function convertirNumero(valor) {

  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {
    return 0;
  }

  if (
    typeof valor === "number"
  ) {
    return Number.isFinite(valor)
      ? valor
      : 0;
  }

  let texto =
    String(valor)
      .trim()
      .replace(/\s/g, "")
      .replace(/Bs/gi, "")
      .replace(/\$/g, "")
      .replace(/USDT/gi, "")
      .replace(/USD/gi, "");

  const ultimoPunto =
    texto.lastIndexOf(".");

  const ultimaComa =
    texto.lastIndexOf(",");


  // 15.447,20
  if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1 &&
    ultimaComa > ultimoPunto
  ) {

    texto =
      texto
        .replace(/\./g, "")
        .replace(",", ".");
  }


  // 15,447.20
  else if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1 &&
    ultimoPunto > ultimaComa
  ) {

    texto =
      texto.replace(/,/g, "");
  }


  // 15447,20
  else if (
    ultimaComa !== -1
  ) {

    const partes =
      texto.split(",");

    if (
      partes.length === 2 &&
      partes[1].length <= 2
    ) {

      texto =
        `${partes[0]}.${partes[1]}`;
    }

    else {

      texto =
        texto.replace(/,/g, "");
    }
  }


  // 15.447 o 15447.20
  else if (
    ultimoPunto !== -1
  ) {

    const partes =
      texto.split(".");

    if (
      partes.length === 2 &&
      partes[1].length <= 2
    ) {

      // decimal normal
    }

    else {

      texto =
        texto.replace(/\./g, "");
    }
  }


  const numero =
    Number(texto);

  return Number.isFinite(numero)
    ? numero
    : 0;
}


