    ) {

      texto =
        `${partes[0]}.${partes[1]}`;
    }

    else {

      texto =
        texto.replace(/,/g, "");
    }
  }


  // 15.447 o 15447.20
  else if (
    ultimoPunto !== -1
  ) {

    const partes =
      texto.split(".");

    if (
      partes.length === 2 &&
      partes[1].length <= 2
    ) {

      // decimal normal
    }

    else {

      texto =
        texto.replace(/\./g, "");
    }
  }


  const numero =
    Number(texto);

  return Number.isFinite(numero)
    ? numero
    : 0;
}


function formatoSheet(numero) {

  return Number(numero || 0)
    .toFixed(2)
    .replace(".", ",");
}


// ======================================================
// DATOS DE DESTINO
// ======================================================

const cuentaDestino =
  limpiar(
    transferencia.CUENTA_DESTINO
  );

const montoEntrada =
  Number(
    transferencia.MONTO_ENTRADA || 0
  );

const rutaDestino =
  limpiar(
    transferencia.RUTA_DESTINO
  );


// ======================================================
// VALIDACIONES
// ======================================================

if (!cuentaDestino) {

  throw new Error(
    "CUENTA_DESTINO vacía"
  );
}


if (!rutaDestino) {

  throw new Error(
    "RUTA_DESTINO vacía"
  );
}


if (
  !Number.isFinite(montoEntrada) ||
  montoEntrada <= 0
) {

  throw new Error(
