else {

  throw new Error(
    `CUENTA_DESTINO no reconocida: ${cuentaDestino}`
  );
}


// ======================================================
// ROW NUMBER REAL DEL DESTINO
// ======================================================

const rowNumberDestino =
  Number(
    filaDestino.row_number || 0
  );


if (
  !Number.isFinite(rowNumberDestino) ||
  rowNumberDestino <= 0
) {

  throw new Error(
    JSON.stringify({
      error:
        "ROW_NUMBER_DESTINO_INVALIDO",

      cuentaDestino,

      row_number:
        filaDestino.row_number
    })
  );
}


// ======================================================
// LEER SALDO ACTUAL DESDE LA COLUMNA CORRECTA
// ======================================================

const valorCrudoDestino =
  filaDestino[columnaDestino];


const saldoDestinoActual =
  convertirNumero(
    valorCrudoDestino
  );


if (
  !Number.isFinite(saldoDestinoActual)
) {

