      cuentaDestino,

      columnaDestino,

      valorCrudoDestino
    })
  );
}


// ======================================================
// SUMAR AL DESTINO
// ======================================================

const saldoDestinoNuevo =
  Number(
    (
      saldoDestinoActual +
      montoEntrada
    ).toFixed(2)
  );


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      ...transferencia,

      RUTA_DESTINO:
        rutaDestino,


      // -----------------------------------------------
      // DESTINO
      // -----------------------------------------------

      FILA_DESTINO:
        rowNumberDestino,

      COLUMNA_DESTINO:
        columnaDestino,

      SALDO_DESTINO_ACTUAL:
        saldoDestinoActual,

      SALDO_DESTINO_NUEVO:
        saldoDestinoNuevo,

      SALDO_DESTINO_NUEVO_SHEET:
        formatoSheet(
          saldoDestinoNuevo
        )
    }
  }
];

