const data = { ...$json };


// ======================================================
// HELPERS
// ======================================================

function limpiar(valor) {
  return String(valor ?? "").trim();
}

function numero(valor) {
  const n = Number(valor || 0);
  return Number.isFinite(n) ? n : 0;
}


// ======================================================
// DATOS PRINCIPALES
// ======================================================

const telegramId =
  limpiar(
    data.TELEGRAM_ID ||
    data.chat_id ||
    ""
  );

const registradoPor =
  limpiar(
    data.REGISTRADO_POR ||
    ""
  );

const cliente =
  limpiar(
    data.CLIENTE ||
    ""
  );

const correo =
  limpiar(
    data.CORREO ||
    ""
  );

const detalleOperacion =
  Array.isArray(data.DETALLE_OPERACION)
    ? data.DETALLE_OPERACION
    : [];

const totalRenovaciones =
  numero(
    data.TOTAL_RENOVACIONES ||
    detalleOperacion.length
  );

const totalNetflix =
  numero(
    data.TOTAL_NETFLIX
  );

const totalFlujoTV =
  numero(
    data.TOTAL_FLUJOTV
  );


// ======================================================
// VALIDACIONES
// ======================================================

if (!telegramId) {
  throw new Error(
    "RENOVACION_MULTIPLE: TELEGRAM_ID vacío"
  );
}

if (!cliente) {
  throw new Error(
    "RENOVACION_MULTIPLE: CLIENTE vacío"
  );
}

if (!detalleOperacion.length) {
  throw new Error(
    "RENOVACION_MULTIPLE: DETALLE_OPERACION vacío"
  );
}

if (
  totalRenovaciones !==
  detalleOperacion.length
) {
  throw new Error(
    JSON.stringify({
      error:
        "TOTAL_RENOVACIONES_NO_COINCIDE",

      TOTAL_RENOVACIONES:
        totalRenovaciones,

      ITEMS_DETALLE:
        detalleOperacion.length
    })
  );
}


// ======================================================
// VALIDAR CADA SERVICIO
// ======================================================

for (
  let i = 0;
  i < detalleOperacion.length;
  i++
) {

  const detalle =
    detalleOperacion[i] || {};

  const servicio =
    limpiar(
      detalle.SERVICIO
    ).toUpperCase();

  const modalidad =
    limpiar(
      detalle.MODALIDAD
    ).toUpperCase();

  const duracion =
    numero(
      detalle.DURACION
    );

  if (
    servicio !== "NETFLIX" &&
    servicio !== "FLUJOTV"
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "SERVICIO_MULTIPLE_INVALIDO",

        item:
          i + 1,

        servicio
      })
    );
  }

  if (
    modalidad !== "PERFIL" &&
    modalidad !== "COMPLETA"
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "MODALIDAD_MULTIPLE_INVALIDA",

        item:
          i + 1,

        modalidad
      })
    );
  }

  if (
    !Number.isFinite(duracion) ||
    duracion <= 0
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "DURACION_MULTIPLE_INVALIDA",

        item:
          i + 1,

        duracion
      })
    );
  }
}


// ======================================================
// SALIDA
//
// IMPORTANTE:
// Sigue siendo UN SOLO ITEM.
// ======================================================

return [
  {
    json: {

      ...data,

      TELEGRAM_ID:
        telegramId,

      chat_id:
        telegramId,

      REGISTRADO_POR:
        registradoPor,

      CLIENTE:
        cliente,

      CORREO:
        correo,

      TIPO_MOVIMIENTO:
        "INGRESO",

      OPERACION:
        totalRenovaciones === 1
          ? "RENOVACION"
          : "RENOVACION_MULTIPLE",

      SERVICIO:
        totalRenovaciones === 1
          ? detalleOperacion[0].SERVICIO
          : "MULTIPLE",

      MODALIDAD:
        totalRenovaciones === 1
          ? detalleOperacion[0].MODALIDAD
          : "MULTIPLE",

      DURACION:
        totalRenovaciones === 1
          ? detalleOperacion[0].DURACION
          : totalRenovaciones,

      ORIGEN:
        "AUTOMATICO",

      TOTAL_RENOVACIONES:
        totalRenovaciones,

      TOTAL_NETFLIX:
        totalNetflix,

      TOTAL_FLUJOTV:
        totalFlujoTV,

      DETALLE_OPERACION:
        detalleOperacion
    }
  }
];

// Filtramos los items que tengan datos en la columna PRODUCTO_PRECIO
return items.filter(item => {
    // Verificamos si la propiedad existe y no está vacía
    const producto = item.json.PRODUCTO_PRECIO;
    return producto !== undefined && producto !== null && String(producto).trim() !== "";
}).map(item => {
    return {
        json: {
            producto: item.json.PRODUCTO_PRECIO,
            precio: item.json.VALOR_USD || "N/A" // Si no hay precio, pone N/A
        }
    };
});

const filas = $input.all().map(i => i.json);

if (!filas.length) {
  throw new Error("No hay tasas disponibles");
}

// Fecha actual en Venezuela UTC-4
const ahora = new Date();

const vzla = new Date(
  ahora.getTime() - (4 * 60 * 60 * 1000)
);

const hoyVzla =
  vzla.getUTCFullYear() +
  "-" +
  String(vzla.getUTCMonth() + 1).padStart(2, "0") +
  "-" +
  String(vzla.getUTCDate()).padStart(2, "0");

// Filas con fecha válida
const validas = filas
  .filter(f => {
    const dia = String(f.Dia || "").trim();

    return /^\d{4}-\d{2}-\d{2}$/.test(dia);
  })
  .sort((a, b) => {
    return String(b.Dia)
      .localeCompare(String(a.Dia));
  });

if (!validas.length) {
  throw new Error(
    "No se encontró ninguna tasa con fecha válida"
  );
}

// Buscar tasa de hoy
const tasaHoy = validas.find(
  f => String(f.Dia).trim() === hoyVzla
);

// Si no hay de hoy, usar la última disponible
const seleccionada =
  tasaHoy || validas[0];

return [
  {
    json: {
      ...seleccionada,

      TASA_USADA_FECHA:
        String(seleccionada.Dia),

      TASA_ES_DE_HOY:
        String(seleccionada.Dia) === hoyVzla,

      FECHA_HOY_VENEZUELA:
        hoyVzla
    }
  }
];

// ======================================================
// FUENTES
// ======================================================

const data =
  $('CODE - Preparar Renovacion Multiple')
    .first()
    .json;


// Lista de precios:
//
// BUSCAR PRECIOS1
// → Code in JavaScript
//
// Devuelve:
// {
//   producto: "...",
//   precio: 4
// }
// ======================================================

const precios =
  $('Code in JavaScript')
    .all()
    .map(item => item.json);


// Tasa vigente
const filaTasa =
  $('seleccionar tasa vigente3')
    .first()
    .json;


// ======================================================
// HELPERS
// ======================================================

function limpiar(valor) {
  return String(valor ?? "").trim();
}


function normalizar(valor) {

  return limpiar(valor)
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}


function numero(valor) {

  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {
    return 0;
  }


  if (
    typeof valor === "number"
  ) {

    return Number.isFinite(valor)
      ? valor
      : 0;
  }


  let texto =
    String(valor)
      .trim()
      .replace(/\$/g, "")
      .replace(/USD/gi, "")
      .replace(/USDT/gi, "")
      .replace(/\s/g, "");


  const ultimoPunto =
    texto.lastIndexOf(".");

  const ultimaComa =
    texto.lastIndexOf(",");


  // Ejemplo:
  // 1.234,50
  if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1 &&
    ultimaComa > ultimoPunto
  ) {

    texto =
      texto
        .replace(/\./g, "")
        .replace(",", ".");
  }


  // Ejemplo:
  // 1,234.50
  else if (
    ultimoPunto !== -1 &&
    ultimaComa !== -1 &&
    ultimoPunto > ultimaComa
  ) {

    texto =
      texto.replace(/,/g, "");
  }


  // Ejemplo:
  // 1234,50
  else if (
    ultimaComa !== -1
  ) {

    texto =
      texto.replace(",", ".");
  }


  const n =
    Number(texto);


  return Number.isFinite(n)
    ? n
    : 0;
}


// ======================================================
// DETALLE DE RENOVACIONES
// ======================================================

const detalle =
  Array.isArray(data.DETALLE_OPERACION)
    ? data.DETALLE_OPERACION
    : [];


if (!detalle.length) {

  throw new Error(
    "DETALLE_OPERACION vacío en cálculo múltiple"
  );
}


if (!precios.length) {

  throw new Error(
    "No llegaron precios al cálculo múltiple"
  );
}


// ======================================================
// NORMALIZAR TABLA DE PRECIOS
// ======================================================

const tablaPrecios =
  precios
    .map(fila => {

      const producto =
        limpiar(
          fila.producto ||
          fila.PRODUCTO_PRECIO ||
          ""
        );


      const precio =
        numero(
          fila.precio ||
          fila.VALOR_USD ||
          0
        );


      return {

        producto,

        productoNormalizado:
          normalizar(producto),

        precio
      };
    })
    .filter(fila =>
      fila.producto &&
      fila.precio > 0
    );


// ======================================================
// BUSCAR PRECIO BASE
//
// TABLA:
//
// NETFLIX + PERFIL
// NETFLIX + COMPLETA
// FLUJOTV + PERFIL
// FLUJOTV + COMPLETA
//
// NO buscamos duración en PRODUCTO_PRECIO.
// ======================================================

function buscarPrecioBase(detalleItem) {

  const servicio =
    normalizar(
      detalleItem.SERVICIO
    );


  const modalidad =
    normalizar(
      detalleItem.MODALIDAD
    );


  // ====================================================
  // BUSCAR SERVICIO
  // ====================================================

  const candidatosServicio =
    tablaPrecios.filter(fila => {

      if (
        servicio === "NETFLIX"
      ) {

        return (
          fila.productoNormalizado
            .includes("NETFLIX")
        );
      }


      if (
        servicio === "FLUJOTV"
      ) {

        return (
          fila.productoNormalizado
            .includes("FLUJOTV")
        );
      }


      return false;
    });


  // ====================================================
  // BUSCAR MODALIDAD
  // ====================================================

  let encontrado = null;


  if (
    modalidad === "PERFIL"
  ) {

    encontrado =
      candidatosServicio.find(fila =>
        fila.productoNormalizado
          .includes("PERFIL")
      );
  }


  else if (
    modalidad === "COMPLETA"
  ) {

    encontrado =
      candidatosServicio.find(fila =>
        fila.productoNormalizado
          .includes("COMPLETA")
      );
  }


  // ====================================================
  // VALIDAR
  // ====================================================

  if (!encontrado) {

    throw new Error(
      JSON.stringify({
        error:
          "PRECIO_BASE_NO_ENCONTRADO",

        SERVICIO:
          detalleItem.SERVICIO,

        MODALIDAD:
          detalleItem.MODALIDAD,

        productosDisponibles:
          tablaPrecios.map(
            fila => fila.producto
          )
      })
    );
  }


  return encontrado;
}


// ======================================================
// CALCULAR CADA RENOVACIÓN
// ======================================================

const detalleCalculado = [];

let totalUsd = 0;


for (
  const item of detalle
) {

  const precioEncontrado =
    buscarPrecioBase(item);


  const precioMensual =
    Number(
      precioEncontrado
        .precio
        .toFixed(2)
    );


  // ----------------------------------------------------
  // DURACIÓN
  //
  // Ya viene normalizada desde:
  // CODE - Preparar Renovacion Multiple
  //
  // 1 mes   → 1
  // 3 meses → 3
  // 15 días → 0.5
  // ----------------------------------------------------

  const duracion =
    numero(
      item.DURACION
    );


  if (
    !Number.isFinite(duracion) ||
    duracion <= 0
  ) {

    throw new Error(
      JSON.stringify({
        error:
          "DURACION_INVALIDA_AL_CALCULAR_PRECIO",

        item
      })
    );
  }


  // ----------------------------------------------------
  // PRECIO DE ESTA RENOVACIÓN
  //
  // precio mensual × duración comprada
  // ----------------------------------------------------

  const subtotalUsd =
    Number(
      (
        precioMensual *
        duracion
      ).toFixed(2)
    );


  totalUsd +=
    subtotalUsd;


  // ----------------------------------------------------
  // GUARDAR DETALLE CALCULADO
  // ----------------------------------------------------

  detalleCalculado.push({

    ...item,

    PRODUCTO_PRECIO:
      precioEncontrado.producto,

    PRECIO_MENSUAL_USD:
      precioMensual,

    SUBTOTAL_USD:
      subtotalUsd
  });
}


// ======================================================
// TOTAL FINAL
// ======================================================

totalUsd =
  Number(
    totalUsd.toFixed(2)
  );


// ======================================================
// TASA VIGENTE
// ======================================================

const tasa =
  numero(
    filaTasa["Promedio Tasa"] ||
    filaTasa.TASA ||
    0
  );


if (
  !Number.isFinite(tasa) ||
  tasa <= 0
) {

  throw new Error(
    JSON.stringify({
      error:
        "TASA_MULTIPLE_INVALIDA",

      tasaRecibida:
        filaTasa["Promedio Tasa"]
    })
  );
}


// ======================================================
